package Q2;
import javax.swing.*;import java.awt.*;import java.awt.event.*;import java.util.*;
public class AppointmentDesk extends JFrame{private final JTextField patient=new JTextField(12);private final JComboBox<String>dept=new JComboBox<>(new String[]{"Cardiology","Dental"}),doctor=new JComboBox<>(),slot=new JComboBox<>(new String[]{"09:00","10:00","11:00"});private final Map<String,java.util.List<String>>doctors=Map.of("Cardiology",java.util.List.of("Dr Rao","Dr Kumar"),"Dental",java.util.List.of("Dr Devi","Dr John"));private boolean booking=false;public AppointmentDesk(){super("OP Appointment Desk");setLayout(new GridLayout(5,2,5,5));add(new JLabel("Patient ID"));add(patient);add(new JLabel("Department"));add(dept);add(new JLabel("Doctor"));add(doctor);add(new JLabel("Time slot"));add(slot);JButton book=new JButton("Book");add(book);JLabel status=new JLabel("Ready");add(status);dept.addActionListener(e->{doctor.removeAllItems();for(String d:doctors.get((String)dept.getSelectedItem()))doctor.addItem(d);});dept.setSelectedIndex(0);book.addActionListener(e->{if(patient.getText().isBlank()||doctor.getSelectedItem()==null){status.setText("Enter patient and doctor");return;}booking=true;status.setText("Booked (demo): "+doctor.getSelectedItem()+" at "+slot.getSelectedItem());booking=false;});addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){if(booking&&JOptionPane.showConfirmDialog(AppointmentDesk.this,"Booking in progress. Close?","Confirm",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);else dispose();}});setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);pack();setLocationRelativeTo(null);}public static void main(String[]x){SwingUtilities.invokeLater(()->new AppointmentDesk().setVisible(true));}}
